DISTINCT_WELLS = {"pred": "not", "of": {"pred": "within_dist", "a": "tube_1", "b": "tube_2", "tol": 0.015, "axes": "xy"}}
PRESS_JOINT = 'button_prog_1_key'


def in_start_site(obj, sites, size):
    """{obj} released and at rest back in the hole it started in"""
    size = np.asarray(size)
    return _Baseline(lambda env: next((s for s in sites if _in_site_geom(env, obj, s, size)), None),
                     lambda env, site: site is not None and _in_site_geom(env, obj, site, size) and _released_at_rest(env, obj))


def in_start_site_goal_reader(env, obj, sites, size):
    d, ob = env.data, env.model.body(obj).id
    start_site = env.model.site(next(s for s in sites if _in_site_geom(env, obj, s, np.asarray(size)))).id
    return lambda: (max(float(np.linalg.norm((d.xpos[ob] - d.site_xpos[start_site])[:2])) - float(max(size[:2])), 0.0), None)


in_start_site.goal_reader = in_start_site_goal_reader


def subtasks():
    edge, state = PressEdge(PRESS_JOINT), dict(presses=0, ready=False, step=-1, valid=False)

    def press(s):
        down = bool(edge.update(s.env)) and s.step > 0
        state["presses"] += int(down)
        both = all(s.tree(t) for t in LOADED) and s.tree(DISTINCT_WELLS)
        valid = state["ready"] and both and down and state["presses"] == 1
        state["ready"] = state["ready"] or (both and state["presses"] == 0)
        return valid
    return [
        Subtask('pick the first tube and seat it in a machine well', lambda s: s.tree(LOADED[0]), ever=True),
        Subtask('pick the second tube and seat it in a machine well', lambda s: s.tree(LOADED[1]), ever=True),
        Subtask('press program 1 once', press, ever=True, objects=(PRESS_JOINT,)),
        Subtask('pick the first tube out of the well and return it to its own rack hole', lambda s: s.tree(RETURNED[0]) and state["presses"] == 1, needs=(2,), end_needs=(2,)),
        Subtask('pick the second tube out of the well and return it to its own rack hole', lambda s: s.success(), needs=(2,), end_needs=(2,)),
    ]


def INVARIANT(s):
    return s.tree({"pred": "all", "of": [{"pred": "all", "of": [{"pred": "axis_up", "obj": "tube_rack", "axis": [0, 0, 1], "tol_deg": 15.0}, {"pred": "over_site", "obj": "tube_rack", "site": "table_top", "lo": [-0.297, -0.297, 0.0005], "hi": [0.297, 0.297, 0.0185]}]}, {"pred": "axis_up", "obj": "tube_1", "axis": [0, 0, 1], "tol_deg": 15.0}, {"pred": "axis_up", "obj": "tube_2", "axis": [0, 0, 1], "tol_deg": 15.0}]})
